  const back = `<div class="top"><button class="ibtn" data-a="back" aria-label="Back">${ic('back')}</button><button class="ibtn" data-a="cedit" data-id="${id}" aria-label="Edit card" style="font-size:20px;line-height:1">⋯</button></div>`;
