    const dated = open.filter(i => i.date).sort((a,b) => a.date.localeCompare(b.date));
    const end = c.deadline && c.deadline > t ? c.deadline : (dated.length ? dated[dated.length - 1].date : addD(t, 7)); const span = Math.max(1, diff(t, end));
    const pts = dated.filter(i => i.date >= t && i.date <= end).map((i, k) => `<span class="pt" style="left:${diff(t, i.date) / span * 100}%" title="${esc(i.t)}"><i style="background:${c.color}"></i></span>`).join('');
    const doneIts = tasks.filter(i => i.done);
