function week(){
  const t = T(), days = [], prev = []; for (let k = 6; k >= 0; k--) { days.push(addD(t,-k)); prev.push(addD(t,-k-7)); }
  const total = days.reduce((a,d) => a + doneCountOn(d), 0), ptotal = prev.reduce((a,d) => a + doneCountOn(d), 0);
  const bestDay = days.reduce((b,d) => doneCountOn(d) > doneCountOn(b) ? d : b, days[0]);
  const DNC2 = ['Sunday','Monday','Tuesday','Wednesday','Thursday','Friday','Saturday'];
  const rows = S.cards.map(c => { if (c.type === 'habit') { const its = S.items.filter(i => i.card === c.id && i.repeat); const n = days.filter(d => its.some(i => i.doneDates.includes(d))).length; return {c, label: n + ' / 7', pct: n / 7 * 100}; }
    const n = S.items.filter(i => i.card === c.id && i.done && i.date && i.date >= days[0]).length; const all = S.items.filter(i => i.card === c.id && !i.repeat).length; return {c, label: n + ' ' + plural(n,'task','tasks','tasks') + ' done', pct: all ? Math.min(100, n / all * 100 + 8) : 0}; });
  const habits = S.cards.filter(c => c.type === 'habit'), good = habits.filter(c => streak(c) >= 5), bad = habits.filter(c => gap(c) >= 3);
  const newM = S.moments.filter(m => m.d && m.d >= days[0] && hasPic(m)).slice(0,3);
  const dots = []; for (let k = 0; k < 28; k++) dots.push(`<i style="width:6px;height:6px;border-radius:50%;background:${k < Math.min(28, total) ? 'var(--ink)' : 'var(--hair)'}"></i>`);
  return `<div class="scr"><div class="top"><button class="ibtn" data-a="back" aria-label="Back">${ic('back')}</button><span class="brand"><b class="aurora-wordmark" role="img" aria-label="Aurora"></b></span></div>
    <h1 class="h1">Your week.</h1><!--BD-->
    <section class="panel glass" style="display:flex;align-items:center;gap:18px"><span style="display:grid;grid-template-columns:repeat(7,6px);gap:5px">${dots.join('')}</span><span style="display:flex;flex-direction:column;gap:4px"><b style="font:800 44px/1 var(--f-head)">${total}</b><span class="sub" style="color:var(--ink)">check-ins. ${total >= ptotal ? 'A week to build on.' : 'Last week: ' + ptotal + '.'}</span></span></section>
    <section class="panel glass" style="display:flex;flex-direction:column;gap:12px">${rows.map(r => `<div style="display:flex;flex-direction:column;gap:6px"><span class="rowh"><span style="font-size:15px;font-weight:600">${esc(r.c.name)}</span><span class="sub">${r.label}</span></span><span class="bar" style="height:6px"><i style="width:${r.pct}%;background:${r.c.color}"></i></span></div>`).join('')}</section>
    <div style="display:grid;grid-template-columns:1fr 1fr;gap:8px"><div class="panel glass"><span class="cap">Best day</span><div style="font:800 22px/1.1 var(--f-head);padding-top:6px">${DNC2[dOf(bestDay).getDay()]}</div><span class="sub">${doneCountOn(bestDay)} done</span></div>
      <button class="panel glass" data-a="tab" data-v="board" style="text-align:left"><span class="cap">New moments</span><span style="display:flex;gap:4px;padding-top:8px">${newM.length ? newM.map(m => `<img src="${m.src || IMGS[m.img]}" alt="" style="width:36px;height:36px;border-radius:9px;object-fit:cover">`).join('') : '<span class="sub">none yet</span>'}</span></button></div>
    <div class="insight" style="--c:${bad[0] ? bad[0].color : '#3fbf7f'}">${good.length ? esc(good.map(c => c.name).join(', ')) + ' keeps the rhythm. ' : ''}${bad.length ? '<b>' + esc(bad[0].name) + ': ' + gap(bad[0]) + ' days away</b> — plan one small thing for next week?' : 'Your habits are moving along.'}</div>
    <div style="display:grid;grid-template-columns:2fr 1fr;gap:8px"><button class="cta" data-a="goplan">Plan your week</button><button class="cta ghost" data-a="story">Share</button></div></div>`;
}

