function parseWhen(txt){
 const normalized=txt.normalize('NFD').replace(/[\u0300-\u036f]/g,'').toLowerCase();
 const today=T(),days={monday:1,tuesday:2,wednesday:3,thursday:4,friday:5,saturday:6,sunday:0,pondeli:1,utery:2,streda:3,ctvrtek:4,patek:5,sobota:6,nedele:0};
 const dateMatch=/\b(day after tomorrow|today|tomorrow|dnes|zitra|pozitri|monday|tuesday|wednesday|thursday|friday|saturday|sunday|pondeli|utery|streda|ctvrtek|patek|sobota|nedele)\b/.exec(normalized);
 let date=null,time=null,ranges=[];
 if(dateMatch){const word=dateMatch[0];date=/^(today|dnes)$/.test(word)?today:/^(tomorrow|zitra)$/.test(word)?addD(today,1):/^(day after tomorrow|pozitri)$/.test(word)?addD(today,2):addD(today,(days[word]-dOf(today).getDay()+7)%7||7);ranges.push([dateMatch.index,dateMatch.index+word.length]);}
 const tm=/\b(at\s+|v\s+)?(\d{1,2})(?::(\d{2}))?\s*(am|pm)?\b/i.exec(normalized);
 if(tm&&(date||tm[1]||tm[3]||tm[4])){let hour=Number(tm[2]),minute=Number(tm[3]||0);const meridiem=tm[4];if(minute<60&&((meridiem&&hour>=1&&hour<=12)||(!meridiem&&hour<24))){if(meridiem)hour=hour%12+(meridiem==='pm'?12:0);time=pad(hour)+':'+pad(minute);if(!date)date=today;ranges.push([tm.index,tm.index+tm[0].trimEnd().length]);}}
 let clean=txt;for(const [a,b] of ranges.sort((a,b)=>b[0]-a[0]))clean=clean.slice(0,a)+clean.slice(b);
 return {date,time,clean:clean.replace(/\s+/g,' ').trim()};
}


