 function act(a){
  if(a==='login')openAuth&&openAuth('login');
  else if(a==='password')openAuth&&openAuth('password');
  else if(a==='sync'){if(blocked&&last.includes('another account'))return;blocked=false;sync(true)}
  else if(a==='logout'){if(busy){status('Wait for syncing to finish.');return}client.auth.signOut({scope:'local'}).then(({error})=>{if(error)status(failure(error));else sessionChanged(null)})}
 }
